examples.template:
MonarchButton(text = {{trigger}}, onClick = { choosing = true }, variant = MonarchButtonVariant.Secondary)
if (choosing) {
    MonarchDialog(
        onDismissRequest = { choosing = false },
        title = {{title}},
        description = {{description}},
        actions = {
            MonarchButton(text = "Cancel", onClick = { choosing = false }, variant = MonarchButtonVariant.Ghost)
            MonarchButton(text = {{confirmLabel}}, onClick = { choosing = false }, variant = MonarchButtonVariant.Primary)
        },
    ) {
        Column(modifier = Modifier.selectableGroup()) {
            MonarchRadioRow(
                selected = audience == {{choices.0.value}},
                onClick = { audience = {{choices.0.value}} },
                label = {{choices.0.label}},
                description = {{choices.0.description}},
            )
            MonarchRadioRow(
                selected = audience == {{choices.1.value}},
                onClick = { audience = {{choices.1.value}} },
                label = {{choices.1.label}},
                description = {{choices.1.description}},
            )
        }
    }
}

examples.code:
MonarchButton(text = "Save view", onClick = { choosing = true }, variant = MonarchButtonVariant.Secondary)
if (choosing) {
    MonarchDialog(
        onDismissRequest = { choosing = false },
        title = "Who can see this view?",
        description = "You can change this later from the view’s settings.",
        actions = {
            MonarchButton(text = "Cancel", onClick = { choosing = false }, variant = MonarchButtonVariant.Ghost)
            MonarchButton(text = "Save view", onClick = { choosing = false }, variant = MonarchButtonVariant.Primary)
        },
    ) {
        Column(modifier = Modifier.selectableGroup()) {
            MonarchRadioRow(
                selected = audience == "private",
                onClick = { audience = "private" },
                label = "Only me",
                description = "The view is listed only for you.",
            )
            MonarchRadioRow(
                selected = audience == "shared",
                onClick = { audience = "shared" },
                label = "Everyone in the workspace",
                description = "Members see it in their sidebar and can open it.",
            )
        }
    }
}
